import math
import numpy as np

LOOKBACK = 96
ARM_BARS = 16
RISK = 0.01
RISK_ATR = 3.0
TP_ATR = 3.0


def calc_size(close, atr):
    if not (atr > 0) or math.isnan(atr):
        return 0.05
    s = RISK * close / (RISK_ATR * atr)
    return max(0.05, min(1.0, s))


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    atr = ind.atr(hist, 14)[-1]

    # Detect a TP fill / external flatten
    if pos == 0.0 and state.get("dir", 0) != 0:
        state["dir"] = 0

    # 4h trend filter on the completed 4h candle
    h4 = hist.htf(240)
    trend = 0
    if len(h4.close) >= 20:
        e = ind.ema(h4.close, 20)[-1]
        c4 = h4.close[-1]
        if not math.isnan(e):
            if c4 > e:
                trend = 1
            elif c4 < e:
                trend = -1

    # Trigger checks using setups armed on earlier bars
    long_sig = False
    short_sig = False
    if state.get("l_arm", False):
        age = t - state["l_t"]
        if age > ARM_BARS:
            state["l_arm"] = False
        elif age >= 1 and hist.low[-1] <= state["l_lvl"] and trend == 1:
            long_sig = True
    if state.get("s_arm", False):
        age = t - state["s_t"]
        if age > ARM_BARS:
            state["s_arm"] = False
        elif age >= 1 and hist.high[-1] >= state["s_lvl"] and trend == -1:
            short_sig = True

    # Arm new setups (level conditions, checked every bar)
    if len(hist) > LOOKBACK:
        ph = ind.highest(hist.high, LOOKBACK)[-2]
        pl = ind.lowest(hist.low, LOOKBACK)[-2]
        if not math.isnan(ph) and close > ph:
            state["l_arm"] = True
            state["l_t"] = t
            state["l_lvl"] = float(ph)
        if not math.isnan(pl) and close < pl:
            state["s_arm"] = True
            state["s_t"] = t
            state["s_lvl"] = float(pl)

    cur_dir = state.get("dir", 0)
    target = pos
    new_dir = 0
    if cur_dir == 0:
        if long_sig and not short_sig:
            new_dir = 1
        elif short_sig and not long_sig:
            new_dir = -1
    elif cur_dir == 1 and short_sig:
        new_dir = -1
    elif cur_dir == -1 and long_sig:
        new_dir = 1

    if new_dir != 0:
        size = calc_size(close, atr)
        target = new_dir * size
        state["dir"] = new_dir
        state["entry"] = float(close)
        state["eatr"] = float(atr)
        if new_dir == 1:
            state["l_arm"] = False
        else:
            state["s_arm"] = False

    take = None
    d = state.get("dir", 0)
    if d == 1:
        take = state["entry"] + TP_ATR * state["eatr"]
    elif d == -1:
        take = state["entry"] - TP_ATR * state["eatr"]

    return {"target": float(target), "stop": None, "take": take}

import math
import numpy as np


def clear_trade(state):
    for k in ("active", "dir", "entry", "atr", "entry_t", "be", "size"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    rsi = ind.rsi(close, 14)
    atr_arr = ind.atr(hist, 14)

    c = float(close[-1])
    r_now = float(rsi[-1])
    r_prev = float(rsi[-2]) if len(rsi) >= 2 else float("nan")
    atr_now = float(atr_arr[-1])

    long_sig = False
    short_sig = False
    if not (math.isnan(r_now) or math.isnan(r_prev)):
        long_sig = (r_prev <= 30.0) and (r_now > 30.0)
        short_sig = (r_prev >= 70.0) and (r_now < 70.0)

    # Detect trade ended by stop/take fill
    if state.get("active", False):
        if t > state.get("entry_t", t) and pos == 0.0:
            clear_trade(state)

    if state.get("active", False):
        d = state["dir"]
        entry = state["entry"]
        eatr = state["atr"]
        # Opposite signal closes the trade
        if (d > 0 and short_sig) or (d < 0 and long_sig):
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        # Breakeven ratchet check on close
        if not state.get("be", False):
            if d > 0 and c - entry >= 1.5 * eatr:
                state["be"] = True
            elif d < 0 and entry - c >= 1.5 * eatr:
                state["be"] = True

        stop = entry if state.get("be", False) else None
        take = entry + 6.0 * eatr if d > 0 else entry - 6.0 * eatr
        if t == state["entry_t"]:
            target = state["size"] * d
        else:
            target = pos
        return {"target": target, "stop": stop, "take": take}

    # Flat: look for entries
    if pos == 0.0 and (long_sig or short_sig):
        if math.isnan(atr_now) or atr_now <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        size = 0.01 * c / (1.0 * atr_now)
        size = min(1.0, max(0.05, size))
        d = 1 if long_sig else -1
        state["active"] = True
        state["dir"] = d
        state["entry"] = c
        state["atr"] = atr_now
        state["entry_t"] = t
        state["be"] = False
        state["size"] = size
        take = c + 6.0 * atr_now if d > 0 else c - 6.0 * atr_now
        return {"target": size * d, "stop": None, "take": take}

    return {"target": pos if pos != 0.0 else 0.0, "stop": None, "take": None}
